      dp,
      custom.v = opts$custom_v,
      optimxmethod = opts$optimxmethod,
      genoud = opts$genoud,
      verbose = FALSE
    )
    list(dp = dp, syn = syn)
  }, error = function(e) {
    fit_error <<- conditionMessage(e)
    NULL
  })

  if (!is.null(synth_fit)) {
    dp <- synth_fit$dp
    syn <- synth_fit$syn
    solution_w <- syn$solution.w
    solution_v <- as.numeric(syn$solution.v)
    loss_v <- as.numeric(syn$loss.v)
