    }, numeric(1))
    names(counterfactual) <- as.character(treated_periods)
  } else if (opts$allow_fallback) {
    method_used <- "donor-mean-fallback"
    counterfactual <- fallback_donor_mean(df, treated_unit, donors, treated_periods)
